mapper.select:
select s.id,s.name, s.category_id, s.price, s.description, s.image, s.status, s.update_time as updateTime,c.name as categoryName
from setmeal s left join category c on s.category_id = c.id


        and s.name like CONCAT('%', #{name}, '%')


        and s.category_id = #{categoryId}


        and s.status = #{status}
